"""模拟后端：不出网，用可控的延迟 / 失败率 / 回答长度模拟真实后端。

用途
- 压测排队、配额、伸缩、统计和面板，不消耗任何外部资源；
- 长时间冒烟（跑一晚上）检查服务本身：内存是否上涨、队列是否卡死、
  计数是否对得上、接口是否稳定。

参数（环境变量或面板“设置”里修改，立即生效）
  MOCK_LATENCY      延迟范围秒，如 "1.5-4"
  MOCK_FAIL_RATE    失败概率 0~1
  MOCK_ANSWER_CHARS 回答长度范围，如 "200-1200"
"""
from __future__ import annotations

import random
import threading
import time

_SENTENCES = [
    "This is a simulated answer generated by the mock backend.",
    "It exists so the proxy, queue and dashboard can be exercised safely.",
    "Latency, failure rate and answer length are all configurable.",
    "No external network request is made while producing this text.",
    "模拟后端返回的内容只用于验证服务链路是否正常。",
    "排队、配额、伸缩和统计都会按真实请求的方式计算。",
]

_FAIL_KINDS = [("FAILED", "模拟：页面生成失败"),
               ("EMPTY", "模拟：返回空内容"),
               ("STALE", "模拟：答案归属不明")]


class MockSession:
    def __init__(self, sid: int, cfg, backend: "MockBackend"):
        self.sid = sid
        self.cfg = cfg
        self.backend = backend
        self.served = 0
        self._rng = random.Random()

    def ask(self, question: str, fresh: bool, user_id: str,
            timeout: float | None = None, abort=None) -> dict:
        t0 = time.monotonic()
        lo, hi = self.cfg.mock_latency
        delay = self._rng.uniform(lo, max(lo, hi))
        # 与真实后端同一套契约:一次请求只有一个 deadline,等待不超过剩余预算
        budget = float(timeout) if timeout else delay
        deadline = t0 + max(0.0, budget)
        rec = {"mode": "mock", "solve": 0}
        # 分片等待:服务关停 / 调用方放弃都能在 50ms 内醒过来,不白占槽位
        target = min(delay, max(0.0, deadline - t0))
        waited = 0.0
        while waited < target:
            chunk = min(0.05, target - waited)
            self.backend.stopping.wait(chunk)
            waited += chunk
            if self.backend.stopping.is_set():
                return {**rec, "kind": "CANCELLED",
                        "total_s": round(time.monotonic() - t0, 2),
                        "error": "服务正在关闭"}
            if abort is not None:
                try:
                    if abort():
                        return {**rec, "kind": "CANCELLED",
                                "total_s": round(time.monotonic() - t0, 2),
                                "error": "调用方已放弃请求"}
                except Exception:
                    pass
        if abort is not None:
            try:
                if abort():
                    return {**rec, "kind": "CANCELLED",
                            "total_s": round(time.monotonic() - t0, 2),
                            "error": "调用方已放弃请求"}
            except Exception:
                pass
        if target < delay:
            # 预算不够,没等够时间就当超时返回,不再硬睡
            return {**rec, "kind": "TIMEOUT",
                    "total_s": round(time.monotonic() - t0, 2),
                    "error": "超出本次请求的总时间预算"}
        self.served += 1
        rec["total_s"] = round(time.monotonic() - t0, 2)
        if self._rng.random() < self.cfg.mock_fail_rate:
            kind, err = self._rng.choice(_FAIL_KINDS)
            return {**rec, "kind": kind, "error": err}
        a, b = self.cfg.mock_answer_chars
        target = self._rng.randint(a, max(a, b))
        head = " ".join(question.split())[:60]
        parts = [f"[mock] Q: {head}"]
        while sum(len(p) + 1 for p in parts) < target:
            parts.append(self._rng.choice(_SENTENCES))
        answer = "\n".join(parts)[:max(target, len(parts[0]))]
        return {**rec, "kind": "OK", "answer": answer,
                "answer_chars": len(answer)}

    def info(self) -> dict:
        return {"mock_served": self.served}

    def close(self) -> None:
        pass


class MockBackend:
    name = "mock"

    def __init__(self, cfg):
        self.cfg = cfg
        self.stopping = threading.Event()

    def new_session(self, sid: int) -> MockSession:
        return MockSession(sid, self.cfg, self)

    def close(self) -> None:
        self.stopping.set()
        time.sleep(0)
